tool_input.command:
node -e "
const fs = require('fs');
const html = fs.readFileSync('game.html','utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
try {
  new Function(script.replace(/document\.[a-zA-Z]+\(/g, '(()=>({addEventListener:()=>{},classList:{add(){},remove(){},toggle(){}},querySelectorAll:()=>[],style:{}}))('));
  console.log('parse ok (rough check)');
} catch(e) {
  console.log('ERROR', e.message);
}
"

node --check <(node -e "
const fs=require('fs');
const html=fs.readFileSync('game.html','utf8');
const m=html.match(/<script>([\s\S]*?)<\/script>/);
process.stdout.write(m[1]);
")

node -e "
const fs=require('fs');
const html=fs.readFileSync('game.html','utf8');
const m=html.match(/<script>([\s\S]*?)<\/script>/);
fs.writeFileSync('/tmp/game_script.js', m[1]);
"
node --check /tmp/game_script.js && echo "SYNTAX OK"

